fn has_only_one_distinct_element(arr: &Vec<i32>) -> bool {
    // An empty array or single-element array vacuously has only one distinct value.
    if arr.len() <= 1 {
        return true;
    }
    // Compare every element to the first one.
    let first = arr[0];
    arr.iter().all(|&x| x == first)
}

